INSERT INTO `servicios` (`id_servicio`, `codigo_servicio`, `orden_catalogo`, `id_pais_operacion`, `id_catalogo`, `id_proceso`, `id_proceso_catalogo`, `id_sla`, `id_gestor`, `nombre`, `descripcion`, `tipo_solicitud`, `estado`, `id_pais`, `id_ciudad`, `id_departamento`, `id_prioridad`, `prioridad_valor`, `id_urgencia`, `urgencia_valor`, `id_nivel`, `id_impacto`, `impacto_valor`, `id_estado`, `creado_en`, `actualizado_en`, `proceso`) VALUES
(1, '1.1.8', 8, 1, 1, NULL, 1, 10, 2, 'Cotización de los recursos administrativos.', 'Descripción:\nGestión y elaboración de cotizaciones relacionadas con servicios y recursos administrativos, incluyendo mantenimientos, arreglos locativos, alquileres de equipos (impresoras, computadores, entre otros) y líneas telefónicas.\n\nSolicitud:\nPara una cotización mas eficiente por favor adjuntar y diligenciar el formato de cotización COL-SIG-ADM-FOR-3 F y la siguiente información: Describir detalladamente el tipo de materiales o herramientas, sí aplica algún presupuesto, ficha técnica e imagen y ciudad de entrega\n\nSLA 8 Días', 'REQUERIMIENTO', 'activo', 1, 2, 9, 11, 2, 15, 2, 19, 22, 2, NULL, '2026-07-31 09:00:22', '2026-09-30 17:31:12', 'Adquisiciones'),
(11, NULL, NULL, 2, 7, NULL, NULL, 6, 7, 'reparacion de computador', 'reparar computador', 'Incidente', 'inhabilitado', 34, 36, 35, 41, 1, 37, 1, 38, 39, 1, 40, '2026-08-12 15:58:40', '2026-09-24 16:37:08', NULL),
