(545, '11.2.3', 3, 1, 34, NULL, 49, 2, NULL, 'Asistencia de Impresora', 'Descripción:\nInstalación de impresora por red a algún equipo o por cable.\n\nSolicitud:\nAsistencia de Impresora\n\nSLA 1 Días', 'REQUERIMIENTO', 'activo', NULL, NULL, NULL, 10, 1, 14, 1, 19, 21, 1, NULL, '2026-09-30 09:55:02', '2026-09-30 17:31:29', NULL),
(546, '11.2.4', 4, 1, 34, NULL, 49, 7, NULL, 'Adecuación de Red', 'Descripción:\nAdecuaciones de puntos cableados.\n\nSolicitud:\nCorreo aprobado del jefe del proceso de la adecuación de red\n\nSLA 10 Días', 'REQUERIMIENTO', 'activo', NULL, NULL, NULL, 11, 2, 15, 2, 19, 22, 2, NULL, '2026-09-30 09:55:03', '2026-09-30 17:31:29', NULL),
(547, '11.2.5', 5, 1, 34, NULL, 49, 13, NULL, 'Falla de Impresora', 'Descripción:\nFalla de impresora por red a algún equipo o por cable.\n\nSolicitud:\nReporte de la falla de la impresora\n\nSLA 4 Días', 'INCIDENTE', 'activo', NULL, NULL, NULL, 12, 3, 15, 2, NULL, 23, 3, NULL, '2026-09-30 09:55:03', '2026-09-30 17:31:29', NULL),
(548, '11.2.6', 6, 1, 34, NULL, 49, 13, NULL, 'Solicitud Equipos de Cómputo', 'Descripción:\nSolicitud de equipos al proveedor para la asignación\n\nSolicitud:\nSolicitud equipos de cómputo adjuntar correo de autorización del gerente del proyecto.\n\nSLA 4 Días', 'REQUERIMIENTO', 'activo', NULL, NULL, NULL, 11, 2, 15, 2, 19, 21, 1, NULL, '2026-09-30 09:55:04', '2026-09-30 17:31:29', NULL),
(549, '11.2.7', 7, 1, 34, NULL, 49, 7, NULL, 'Solicitud de periféricos', 'Descripción:\nSolicitud de periféricos como teclado y mouse\n\nSolicitud:\nSolicitud de periféricos adjuntar correo de autorización del gerente del proyecto. Nota: Si el proceso tiene dispositivos en stock se puede entregar sin autorización del gerente.\n\nSLA 10 Días', 'REQUERIMIENTO', 'activo', NULL, NULL, NULL, 10, 1, 14, 1, 19, 21, 1, NULL, '2026-09-30 09:55:05', '2026-09-30 17:31:29', NULL),
(550, '11.2.8', 8, 1, 34, NULL, 49, 2, NULL, 'Creación de usuario Milldesk', 'Descripción:\nCreación de usuario para el ingreso a plataforma de Milldesk\n\nSolicitud:\nCreación de usuario Milldesk\n\nSLA 1 Días', 'REQUERIMIENTO', 'activo', NULL, NULL, NULL, 10, 1, 14, 1, 19, 21, 1, NULL, '2026-09-30 09:55:05', '2026-09-30 17:31:29', NULL),
(551, '11.2.9', 9, 1, 34, NULL, 49, 11, NULL, 'Falla de Equipos', 'Descripción:\nVerificación de equipo por bajo rendimiento o daños\n\nSolicitud:\nAdjuntar imagen de la falla o el daño del equipo.\n\nSLA 2 Días', 'INCIDENTE', 'activo', NULL, NULL, NULL, 11, 2, 15, 2, 19, 21, 1, NULL, '2026-09-30 09:55:07', '2026-09-30 17:31:29', NULL),
(552, '11.2.10', 10, 1, 34, NULL, 49, 11, NULL, 'Copia de seguridad', 'Descripción:\nSolictud para realizar copias de seguridad por cambio de equipo o personal que se retiró.\n\nSolicitud:\nCopia de seguridad\n\nSLA 2 Días', 'REQUERIMIENTO', 'activo', NULL, NULL, NULL, 11, 2, 15, 2, 19, 22, 2, NULL, '2026-09-30 09:55:08', '2026-09-30 17:31:30', NULL),
(553, '11.2.11', 11, 1, 34, NULL, 49, 7, NULL, 'Solicitud de servicio de internet', 'Descripción:\nSolicitud de un nuevo servicio de internet para una bodega.\n\nSolicitud:\nAdjuntar correo de la solicitud de servicio de internet aprobado por Jefe del Administración\n\nSLA 10 Días', 'REQUERIMIENTO', 'activo', NULL, NULL, NULL, 12, 3, 16, 3, 19, 23, 3, NULL, '2026-09-30 09:55:08', '2026-09-30 17:31:30', NULL),
